-- Expand the offline IT glossary with curated Japanese headwords and Chinese/Japanese/English definitions.
-- Idempotent by stable ID. Does not touch user mastery or personal learning records.
INSERT OR IGNORE INTO vocabulary
(id, term, language, reading, meaning_zh, meaning_ja, meaning_en, example, source_module, mastery)
VALUES
('it-local-api','API','ja','エーピーアイ','应用程序编程接口：定义软件组件之间如何请求和交换数据。','ソフトウェア同士が機能やデータをやり取りするためのインターフェース。','An Application Programming Interface defines how software components exchange data.','APIの仕様書を確認してからクライアントを実装する。','软件开发',0),
('it-local-sdk','SDK','ja','エスディーケー','软件开发工具包：帮助开发者使用某个平台或服务的一组工具与库。','特定のプラットフォームやサービス向けの開発に必要なライブラリやツールの一式。','A Software Development Kit provides tools and libraries for building software.','公式SDKの対応バージョンを確認する。','软件开发',0),
('it-local-cli','コマンドラインインターフェース','ja','こまんどらいんいんたーふぇーす','命令行界面：通过输入命令与程序或操作系统交互。','コマンドを文字で入力してプログラムやOSを操作するインターフェース。','A Command-Line Interface lets users interact with software by entering commands.','CLIからビルドとテストを実行する。','开发工具',0),
('it-local-gui','グラフィカルユーザーインターフェース','ja','ぐらふぃかるゆーざーいんたーふぇーす','图形用户界面：通过窗口、图标和控件与系统交互。','ウィンドウやアイコン、ボタンなどを使って操作する画面。','A Graphical User Interface uses visual elements such as windows and buttons.','GUIで設定を変更する。','开发工具',0),
('it-local-ide','統合開発環境','ja','とうごうかいはつかんきょう','集成开发环境：整合代码编辑、构建、调试等功能的软件。','コード編集、ビルド、デバッグなどを統合した開発用ソフトウェア。','An Integrated Development Environment combines editing, building, and debugging tools.','IDEでブレークポイントを設定する。','开发工具',0),
('it-local-git','Git','ja','ぎっと','分布式版本控制系统，用于跟踪文件变更并协作开发。','ファイルの変更履歴を記録し、複数人での開発を支援する分散型バージョン管理システム。','Git is a distributed version control system for tracking changes.','変更をコミットする前に差分を確認する。','版本控制',0),
('it-local-commit','コミット','ja','こみっと','版本控制中的一次记录变更操作。','変更内容を履歴としてリポジトリに記録する操作。','A commit records a set of changes in version control.','意味の分かるメッセージでコミットする。','版本控制',0),
('it-local-branch','ブランチ','ja','ぶらんち','分支：用于隔离开发工作的独立变更线。','作業を分離して並行開発するための変更履歴の枝。','A branch isolates a line of development from other work.','修正用のブランチを作成する。','版本控制',0),
('it-local-merge','マージ','ja','まーじ','合并：把不同分支的变更整合到一起。','複数のブランチの変更を一つに統合する操作。','A merge integrates changes from different branches.','レビューが通ったブランチをmainにマージする。','版本控制',0),
('it-local-pull-request','プルリクエスト','ja','ぷるりくえすと','拉取请求：请求审查并将一个分支的变更合并到另一个分支。','変更内容のレビューとマージを依頼する仕組み。','A pull request proposes changes for review and merging.','プルリクエストで変更点とテスト結果を共有する。','版本控制',0),
('it-local-ci','継続的インテグレーション','ja','けいぞくてきいんてぐれーしょん','持续集成：频繁整合代码，并自动运行构建和测试。','コード変更を継続的に統合し、自動ビルドやテストで問題を早期に検出する手法。','Continuous Integration automatically builds and tests frequent code changes.','CIで回帰テストを実行する。','开发运维',0),
('it-local-cd','継続的デリバリー','ja','けいぞくてきでりばりー','持续交付：让软件始终处于可发布状态，并通过自动化降低发布风险。','ソフトウェアをいつでもリリース可能な状態に保つ開発手法。','Continuous Delivery keeps software ready for release through automated validation.','デプロイ前に継続的デリバリーのパイプラインを確認する。','开发运维',0),
('it-local-cicd-pipeline','CI/CDパイプライン','ja','しーあいしーでぃーぱいぷらいん','CI/CD 流水线：自动执行检查、构建、测试和部署等步骤的流程。','コード検査、ビルド、テスト、デプロイなどを自動実行する一連の処理。','A CI/CD pipeline automates validation, builds, tests, and deployment.','失敗したパイプラインのログを確認する。','开发运维',0),
('it-local-container','コンテナ','ja','こんてな','容器：将应用及其运行依赖隔离打包的轻量化环境。','アプリケーションと依存関係を分離して実行するための軽量な環境。','A container packages an application and its dependencies in an isolated environment.','本番と同じ設定でコンテナを起動する。','云与基础设施',0),
('it-local-docker','Docker','ja','どっかー','用于构建、分发和运行容器的开发平台与工具生态。','コンテナイメージの作成、配布、実行を支援するプラットフォーム。','Docker is a platform for building, distributing, and running containers.','Dockerイメージをビルドして動作を確認する。','云与基础设施',0),
('it-local-kubernetes','Kubernetes','ja','くーばねてぃす','容器编排平台，用于部署、扩缩容和管理容器化应用。','コンテナ化されたアプリケーションの配置、拡張、運用を自動化する基盤。','Kubernetes automates deployment, scaling, and management of containerized applications.','KubernetesのPodの状態を確認する。','云与基础设施',0),
('it-local-serverless','サーバーレス','ja','さーばーれす','无服务器计算：由平台管理底层服务器，开发者主要关注代码和配置。','サーバー基盤の管理をクラウド事業者に任せ、コードや設定に集中する実行方式。','Serverless computing lets developers focus on code while the provider manages infrastructure.','サーバーレス関数の実行時間を監視する。','云与基础设施',0),
('it-local-edge-computing','エッジコンピューティング','ja','えっじこんぴゅーてぃんぐ','边缘计算：在靠近数据源或用户的位置处理数据，以降低延迟。','データ発生源や利用者に近い場所で処理し、遅延や通信量を抑える方式。','Edge computing processes data closer to its source or users.','遅延を減らすためにエッジで処理する。','云与基础设施',0),
('it-local-cdn','コンテンツ配信ネットワーク','ja','こんてんつはいしんねっとわーく','内容分发网络：通过分布式节点缓存和传送内容，改善访问速度与可用性。','分散した配信拠点からコンテンツを届け、表示速度や可用性を高める仕組み。','A Content Delivery Network serves cached content from distributed locations.','静的ファイルをCDNから配信する。','网络基础',0),
('it-local-load-balancer','ロードバランサー','ja','ろーどばんらんさー','负载均衡器：将请求分配到多个服务器或实例。','複数のサーバーやインスタンスに通信を振り分ける装置や機能。','A load balancer distributes requests across multiple servers or instances.','ヘルスチェックに失敗したインスタンスを振り分け対象から外す。','网络基础',0),
('it-local-reverse-proxy','リバースプロキシ','ja','りばーすぷろきし','反向代理：代表后端服务接收客户端请求并转发。','クライアントからの要求を受け、適切なバックエンドへ転送するサーバー。','A reverse proxy receives client requests and forwards them to backend services.','リバースプロキシでTLS終端を行う。','网络基础',0),
('it-local-tls','TLS','ja','てぃーえるえす','传输层安全协议，用于保护网络通信的机密性和完整性并验证服务器身份。','通信の暗号化、完全性保護、サーバー認証などを提供するプロトコル。','TLS protects network communications through encryption and integrity checks.','TLS証明書の有効期限を監視する。','网络与密码技术',0),
('it-local-certificate','デジタル証明書','ja','でじたるしょうめいしょ','数字证书：将身份信息与公钥关联，并由可信机构或体系进行签发。','公開鍵と主体の情報を結び付け、信頼できる認証局などが発行する電子的な証明書。','A digital certificate binds a public key to an identity.','証明書の発行者と有効期限を確認する。','网络与密码技术',0),
('it-local-hash','ハッシュ関数','ja','はっしゅかんすう','哈希函数：将输入映射为固定长度摘要，常用于完整性校验等。','入力データから固定長の値を計算する関数で、完全性確認などに使われる。','A hash function maps input data to a fixed-length digest.','パスワードは適切な方式でハッシュ化して保存する。','网络与密码技术',0),
('it-local-salt','ソルト','ja','そると','盐值：在密码哈希前加入的随机数据，用于降低预计算攻击的效果。','パスワードのハッシュ計算に加えるランダムな値で、同じパスワードでも結果を変える。','A salt is random data added before password hashing to reduce precomputation attacks.','ユーザーごとに異なるソルトを使用する。','网络与密码技术',0),
('it-local-mfa','多要素認証','ja','たようそにんしょう','多因素认证：要求来自不同类别的两个或更多验证因素。','知識・所持・生体など異なる種類の要素を二つ以上用いて本人確認する方式。','Multi-factor authentication verifies identity using two or more different factor types.','管理者アカウントに多要素認証を必須にする。','身份验证与访问控制',0),
('it-local-oidc','OpenID Connect','ja','おーぷんあいでぃーこねくと','基于 OAuth 2.0 的身份认证层，用于验证最终用户身份。','OAuth 2.0を基盤に、利用者の認証情報を標準化して伝える仕組み。','OpenID Connect adds an identity layer on top of OAuth 2.0.','OIDCのIDトークンの署名と発行者を検証する。','身份验证与访问控制',0),
('it-local-oauth','OAuth 2.0','ja','おーおーおーす','授权框架，允许应用在受限权限下访问资源，而不直接共享用户密码。','利用者のパスワードを共有せず、許可された範囲でアプリにリソースへのアクセスを認める認可フレームワーク。','OAuth 2.0 is an authorization framework for delegated access.','OAuthのスコープを必要最小限に設定する。','身份验证与访问控制',0),
('it-local-jwt','JSON Web Token','ja','じぇいだぶりゅーてぃー','JWT：以紧凑格式传递声明的令牌格式，可用于身份与权限信息传递。','JSON形式のクレームをコンパクトに表現するトークン形式。','A JSON Web Token carries claims in a compact token format.','JWTの署名と有効期限を検証する。','身份验证与访问控制',0),
('it-local-sql-injection','SQLインジェクション','ja','えすきゅーえるいんじぇくしょん','SQL 注入：通过不可信输入改变 SQL 语句的预期结构。','入力値によってSQL文の構造を意図せず変えられる脆弱性。','SQL injection occurs when untrusted input alters the intended SQL query.','プレースホルダーを使ってSQLインジェクションを防ぐ。','Web安全',0),
('it-local-xss','クロスサイトスクリプティング','ja','くろすさいとすくりぷてぃんぐ','跨站脚本攻击：让恶意脚本在其他用户的浏览器中执行。','悪意あるスクリプトを利用者のブラウザー上で実行させる攻撃。','Cross-site scripting causes malicious scripts to run in a user''s browser.','出力箇所に応じて適切にエスケープする。','Web安全',0),
('it-local-csp','コンテンツセキュリティポリシー','ja','こんてんつせきゅりてぃぽりしー','内容安全策略：通过浏览器策略限制页面可加载和执行的资源。','ブラウザーが読み込めるリソースや実行できるスクリプトを制限するセキュリティ機能。','Content Security Policy restricts which resources a page may load or execute.','CSPを段階的に導入して違反レポートを確認する。','Web安全',0),
('it-local-cors','クロスオリジンリソース共有','ja','くろすおりじんりそーすきょうゆう','跨源资源共享：通过 HTTP 响应头控制浏览器跨源请求权限。','HTTPヘッダーを用いて、異なるオリジン間のブラウザーアクセスを制御する仕組み。','CORS controls browser cross-origin access through HTTP headers.','許可するオリジンを必要な範囲に限定する。','Web安全',0),
('it-local-rate-limit','レート制限','ja','れーとせいげん','速率限制：限制单位时间内的请求次数，以保护服务和资源。','一定時間内に受け付けるリクエスト数を制限する仕組み。','Rate limiting caps the number of requests allowed in a time window.','ログインAPIにレート制限を設定する。','安全与运维',0),
('it-local-observability','オブザーバビリティ','ja','おぶざーばびりてぃ','可观测性：利用日志、指标和追踪理解系统内部状态。','ログ、メトリクス、トレースなどからシステム内部の状態を把握する能力。','Observability uses logs, metrics, and traces to understand system behavior.','障害調査のためにトレースIDをログへ記録する。','安全与运维',0),
('it-local-logging','ロギング','ja','ろぎんぐ','日志记录：将运行事件和诊断信息写入可查询的记录。','実行時のイベントや診断情報を記録すること。','Logging records runtime events and diagnostic information.','個人情報を含めず必要なイベントをログに残す。','安全与运维',0),
('it-local-metrics','メトリクス','ja','めとりくす','指标：以数值和时间序列描述系统行为或业务状态的数据。','システムやサービスの状態を数値と時系列で表したデータ。','Metrics are numerical time-series measurements of system or service behavior.','エラー率と応答時間のメトリクスを監視する。','安全与运维',0),
('it-local-tracing','分散トレーシング','ja','ぶんさんとれーしんぐ','分布式追踪：跟踪请求在多个服务间的传播和耗时。','複数のサービスをまたぐリクエストの経路や処理時間を追跡する仕組み。','Distributed tracing follows requests across services and records timing.','分散トレーシングで遅延の発生箇所を特定する。','安全与运维',0),
('it-local-slo','サービスレベル目標','ja','さーびすれべるもくひょう','服务等级目标：针对服务可靠性或性能设定的可量化目标。','可用性や応答時間など、サービス品質について定める測定可能な目標。','A Service Level Objective defines a measurable target for service quality.','SLOに基づいてエラーバジェットを管理する。','安全与运维',0),
('it-local-sla','サービスレベル合意','ja','さーびすれべるごうい','服务等级协议：服务提供方与客户之间对服务水平作出的约定。','サービス提供者と利用者の間で、サービス水準や責任を定める合意。','A Service Level Agreement defines agreed service levels and responsibilities.','SLAの可用性条件を契約前に確認する。','项目与服务管理',0),
('it-local-sprint','スプリント','ja','すぷりんと','Scrum 中固定时长的迭代周期，用于完成选定目标和工作项。','スクラムで定める期間を区切った反復単位。','A sprint is a timeboxed iteration in Scrum.','スプリントの目標と完了条件を共有する。','项目与服务管理',0),
('it-local-backlog','バックログ','ja','ばっくろぐ','待办列表：按优先级整理尚待处理的工作或需求。','今後取り組む作業や要求を優先順位付きで管理する一覧。','A backlog is a prioritized list of work to be done.','プロダクトバックログを定期的に見直す。','项目与服务管理',0),
('it-local-acceptance-criteria','受け入れ基準','ja','うけいれきじゅん','验收标准：明确工作成果满足哪些条件才算可接受。','成果物が受け入れ可能と判断される条件を明文化したもの。','Acceptance criteria specify the conditions a deliverable must satisfy.','受け入れ基準をテストケースに反映する。','项目与服务管理',0),
('it-local-regression-test','回帰テスト','ja','かいきてすと','回归测试：确认修改没有破坏既有功能的测试。','変更によって既存機能に不具合が生じていないことを確認するテスト。','Regression testing checks that changes have not broken existing behavior.','修正後に回帰テストを実行する。','测试',0),
('it-local-unit-test','単体テスト','ja','たんたいテスト','单元测试：验证一个函数、类或较小组件的行为。','関数やクラスなど、小さな単位の振る舞いを検証するテスト。','A unit test verifies the behavior of a small unit of code.','境界値を含む単体テストを追加する。','测试',0),
('it-local-integration-test','結合テスト','ja','けつごうテスト','集成测试：验证多个组件或系统之间的交互是否正确。','複数のコンポーネントやシステム間の連携を検証するテスト。','Integration testing verifies interactions between components or systems.','APIとデータベースの結合テストを行う。','测试',0),
('it-local-smoke-test','スモークテスト','ja','すもーくてすと','冒烟测试：快速确认构建或部署后的关键功能能否基本运行。','ビルドやデプロイ後に、主要機能が最低限動作するかを素早く確認するテスト。','A smoke test quickly checks whether critical functionality works.','デプロイ後にログインと主要画面のスモークテストを行う。','测试',0),
('it-local-test-coverage','テストカバレッジ','ja','てすとかばれっじ','测试覆盖率：衡量测试执行覆盖了多少代码或需求的指标。','テストがコードや要求のどの範囲を網羅したかを示す指標。','Test coverage measures how much code or requirements are exercised by tests.','カバレッジだけでなくテスト内容もレビューする。','测试',0),
('it-local-idempotency','冪等性','ja','べきとうせい','幂等性：同一操作重复执行多次，最终效果与执行一次相同。','同じ操作を複数回行っても、結果が一度だけ実行した場合と同じになる性質。','Idempotency means repeating an operation has the same effect as doing it once.','再試行されるAPIでは冪等性を設計する。','API设计',0),
('it-local-pagination','ページネーション','ja','ぺーじねーしょん','分页：将较大结果集分成多页返回或显示。','大量の結果を複数ページに分けて取得・表示する方式。','Pagination divides a large result set into smaller pages.','APIにページネーションと上限値を設ける。','API设计',0),
('it-local-webhook','ウェブフック','ja','うぇぶふっく','Webhook：事件发生时由系统向预先配置的 URL 发送 HTTP 通知。','イベント発生時に、指定されたURLへHTTPリクエストを送って通知する仕組み。','A webhook sends an HTTP request to a configured URL when an event occurs.','Webhookの署名を検証して送信元を確認する。','API设计',0),
('it-local-message-queue','メッセージキュー','ja','めっせーじきゅー','消息队列：暂存待处理消息，使生产者和消费者可以异步协作。','メッセージを一時的に蓄積し、送信側と処理側を非同期に連携させる仕組み。','A message queue buffers messages for asynchronous processing.','キューの滞留数を監視する。','系统架构',0),
('it-local-event-driven','イベント駆動アーキテクチャ','ja','いべんとくどうあーきてくちゃ','事件驱动架构：组件通过发布和消费事件进行协作。','イベントの発行と購読を通じてコンポーネントを連携させる設計方式。','Event-driven architecture coordinates components through published and consumed events.','イベント駆動設計では重複配信への対処を考える。','系统架构',0),
('it-local-cache','キャッシュ','ja','きゃっしゅ','缓存：临时保存可复用的数据，以减少重复计算或访问延迟。','再利用可能なデータを一時保存し、処理時間やアクセス負荷を減らす仕組み。','A cache stores reusable data to reduce latency or repeated work.','キャッシュの有効期限と無効化条件を決める。','系统架构',0),
('it-local-cache-invalidation','キャッシュ無効化','ja','きゃっしゅむこうか','缓存失效：使缓存中的过期或不再正确的数据不再被使用。','古くなったキャッシュを利用しないように削除・更新する処理。','Cache invalidation removes or refreshes stale cached data.','更新後にキャッシュを無効化する。','系统架构',0),
('it-local-connection-pool','コネクションプール','ja','こねくしょんぷーる','连接池：复用数据库等服务的连接，降低频繁建立连接的开销。','データベースなどへの接続を再利用し、接続確立の負荷を抑える仕組み。','A connection pool reuses connections to reduce setup overhead.','接続プールの最大数とタイムアウトを設定する。','数据库',0),
('it-local-index','データベースインデックス','ja','でーたべーすいんでっくす','数据库索引：帮助数据库更快定位数据，但会增加存储和写入维护成本。','検索を高速化する一方、容量や更新コストが増えるデータ構造。','A database index speeds up lookups but adds storage and write overhead.','実行計画を確認して必要なインデックスを追加する。','数据库',0),
('it-local-query-plan','実行計画','ja','じっこうけいかく','查询执行计划：描述数据库准备如何执行查询，包括访问路径和连接方式。','データベースがSQLをどのような手順で実行するかを示す情報。','A query execution plan describes how a database intends to run a query.','実行計画でテーブルスキャンの有無を確認する。','数据库',0),
('it-local-transaction','トランザクション','ja','とらんざくしょん','事务：将一组数据库操作作为一个逻辑工作单元执行。','複数のデータベース操作を一つの論理的な処理単位として扱う仕組み。','A transaction groups database operations into one logical unit of work.','失敗時にトランザクションをロールバックする。','数据库',0),
('it-local-deadlock','デッドロック','ja','でっどろっく','死锁：两个或多个事务相互等待对方持有的资源，导致无法继续。','複数の処理が互いのロック解除を待ち続け、進行できなくなる状態。','A deadlock occurs when processes wait on resources held by each other.','デッドロックのログを調査してロック順序を見直す。','数据库',0),
('it-local-replication','レプリケーション','ja','れぷりけーしょん','复制：将数据或变更复制到其他节点，以提高可用性或读取能力。','データや変更を別のノードへ複製する仕組み。','Replication copies data or changes to other nodes.','レプリケーション遅延を監視する。','数据库',0),
('it-local-data-migration','データベースマイグレーション','ja','でーたべーすまいぐれーしょん','数据库迁移：以可追踪的脚本版本管理结构或数据变更。','スキーマやデータの変更をバージョン管理された手順で適用すること。','A database migration applies versioned schema or data changes.','本番適用前に空のDBでマイグレーションを検証する。','数据库',0),
('it-local-schema','データベーススキーマ','ja','でーたべーすすきーま','数据库模式：定义表、字段、关系和约束等数据结构。','テーブル、列、制約、関係などデータ構造の定義。','A database schema defines tables, columns, constraints, and relationships.','スキーマ変更とアプリの互換性を確認する。','数据库',0),
('it-local-normalization','正規化','ja','せいきか','数据库规范化：组织数据以减少冗余和更新异常。','データの重複や更新時の不整合を減らすために構造を整理すること。','Database normalization structures data to reduce redundancy and anomalies.','更新異常を防ぐためにテーブルを正規化する。','数据库',0),
('it-local-foreign-key','外部キー','ja','がいぶきー','外键：约束一个字段或字段组引用另一个表中的有效记录。','別のテーブルの行を参照し、参照整合性を保つ制約。','A foreign key references rows in another table to enforce referential integrity.','外部キー制約で孤立したレコードを防ぐ。','数据库',0),
('it-local-unique-constraint','一意制約','ja','いちいせいやく','唯一约束：确保一列或多列组合的值不重复。','指定した列または列の組み合わせの値が重複しないようにする制約。','A unique constraint prevents duplicate values in specified columns.','メールアドレスに一意制約を設定する。','数据库',0),
('it-local-soft-delete','論理削除','ja','ろんりさくじょ','逻辑删除：通过状态或删除标记隐藏记录，而非立即物理删除。','レコードを物理的に消さず、削除フラグなどで利用対象から外す方式。','Soft deletion marks records as deleted without immediately removing them.','監査要件を確認して論理削除を採用する。','数据库',0),
('it-local-orm','オブジェクト関係マッピング','ja','おぶじぇくとかんけいまっぴんぐ','对象关系映射：把程序对象与关系数据库中的表和记录关联起来。','プログラムのオブジェクトとリレーショナルデータベースのデータを対応付ける技術。','Object-Relational Mapping maps program objects to relational database data.','ORMが生成するSQLをログで確認する。','数据库',0),
('it-local-dto','データ転送オブジェクト','ja','でーたてんそうおぶじぇくと','数据传输对象：用于在进程或系统边界之间传递数据的对象。','層やシステム間でデータを受け渡すためのオブジェクト。','A Data Transfer Object carries data between layers or systems.','APIレスポンス用のDTOを定義する。','软件设计',0),
('it-local-dependency-injection','依存性注入','ja','いぞんせいちゅうにゅう','依赖注入：由外部提供组件所需依赖，而不是在组件内部自行创建。','必要な依存オブジェクトを外部から渡す設計手法。','Dependency Injection supplies a component''s dependencies from outside.','テスト時に依存性注入でモックを差し替える。','软件设计',0),
('it-local-feature-flag','フィーチャーフラグ','ja','ふぃーちゃーふらぐ','功能开关：通过配置控制某项功能是否对指定用户或环境启用。','設定によって機能の有効・無効を切り替える仕組み。','A feature flag controls whether a feature is enabled for selected users or environments.','フィーチャーフラグで段階的に機能を公開する。','软件发布',0),
('it-local-canary-release','カナリアリリース','ja','かなりありりーす','金丝雀发布：先向少量流量或用户发布，再根据指标决定是否扩大范围。','少数の利用者やトラフィックに先行公開し、結果を見て段階的に拡大する方法。','A canary release exposes a change to a small group before wider rollout.','エラー率を監視しながらカナリアリリースを進める。','软件发布',0),
('it-local-rollback','ロールバック','ja','ろーるばっく','回滚：将变更或系统状态恢复到先前可用版本。','変更を取り消し、以前の状態やバージョンへ戻すこと。','A rollback reverts a change to a previous state or version.','問題が発生したため直前のリリースをロールバックする。','软件发布',0),
('it-local-disaster-recovery','災害復旧','ja','さいがいふっきゅう','灾难恢复：在重大故障或灾害后恢复系统和数据的计划与过程。','重大障害や災害の後に、システムとデータを復旧する計画および手順。','Disaster recovery restores systems and data after a major disruption.','災害復旧手順を定期的に訓練する。','业务连续性与风险管理',0),
('it-local-backup-retention','バックアップ保持期間','ja','ばっくあっぷほじきかん','备份保留期：备份数据按策略保存的时间范围。','バックアップを保存しておく期間を定めたもの。','Backup retention defines how long backup copies are kept.','保持期間と削除ポリシーを確認する。','业务连续性与风险管理',0),
('it-local-rto-rpo-test','復旧訓練','ja','ふっきゅうくんれん','恢复演练：模拟故障以验证恢复步骤、责任分工和目标是否可行。','障害を想定し、復旧手順や役割分担、目標時間を検証する訓練。','A recovery exercise validates procedures, responsibilities, and recovery targets.','定期的な復旧訓練で手順書を更新する。','业务连续性与风险管理',0),
('it-local-data-classification','データ分類','ja','でーたぶんるい','数据分类：按敏感程度、用途或法规要求给数据分级。','機密性や用途、法令要件などに応じてデータを分類すること。','Data classification groups information by sensitivity, use, or requirements.','個人情報と公開情報を分類して保存先を分ける。','数据治理',0),
('it-local-data-retention','データ保持期間','ja','でーたほじきかん','数据保留期限：规定数据应保留多久以及何时删除。','データを保存する期間と削除時期を定めたもの。','Data retention specifies how long data should be kept before deletion.','保存期限を過ぎたログをポリシーに従って削除する。','数据治理',0),
('it-local-pii','個人識別情報','ja','こじんしきべつじょうほう','个人身份信息：能够识别或关联到特定个人的信息，具体范围依法规定义。','個人を識別または特定の個人に結び付けられる情報。適用法令により範囲が異なる。','Personally identifiable information can identify or be linked to an individual, depending on the applicable definition.','ログに不要な個人識別情報を記録しない。','数据治理',0),
('it-local-data-lineage','データリネージ','ja','でーたりねーじ','数据血缘：记录数据从来源到转换、存储和使用的路径。','データの取得元から加工・保存・利用までの流れを追跡する情報。','Data lineage tracks data from its source through transformations and use.','データリネージでレポートの数値の由来を確認する。','数据治理',0),
('it-local-availability','可用性','ja','かようせい','可用性：系统在需要时能够提供服务的程度。','必要なときにシステムやサービスを利用できる度合い。','Availability describes how reliably a system is accessible when needed.','可用性の目標値と測定方法を決める。','可靠性',0),
('it-local-latency','レイテンシ','ja','れいてんし','延迟：请求发出到响应返回之间的时间。','要求を送ってから応答を受け取るまでの時間。','Latency is the time between a request and its response.','p95レイテンシを監視する。','性能',0),
('it-local-throughput','スループット','ja','するーぷっと','吞吐量：单位时间内系统完成或处理的工作量。','単位時間あたりに処理できるデータ量や要求数。','Throughput measures how much work a system processes per unit of time.','負荷試験でスループットを測定する。','性能',0),
('it-local-bottleneck','ボトルネック','ja','ぼとるねっく','瓶颈：限制系统整体性能或处理能力的环节。','システム全体の性能や処理能力を制限する部分。','A bottleneck is the component that limits overall system performance.','プロファイラーでボトルネックを特定する。','性能',0),
('it-local-load-testing','負荷テスト','ja','ふかてすと','负载测试：在预期或高于预期的负载下测量系统表现。','想定した負荷をかけ、性能や安定性を測定するテスト。','Load testing measures system behavior under expected or elevated workload.','ピーク時の負荷を再現して応答時間を測る。','测试',0),
('it-local-stress-testing','ストレステスト','ja','すとれすてすと','压力测试：将系统推至超出常规负载的条件，以观察极限和失效行为。','通常想定を超える負荷をかけ、限界や障害時の挙動を確認するテスト。','Stress testing pushes a system beyond normal load to observe its limits.','ストレステストで過負荷時の復旧動作を確認する。','测试',0),
('it-local-chaos-engineering','カオスエンジニアリング','ja','かおすえんじにありんぐ','混沌工程：在受控条件下引入故障，验证系统的韧性与恢复能力。','制御された環境で障害を発生させ、システムの耐障害性を検証する手法。','Chaos engineering introduces controlled failures to test resilience.','本番影響を避けた環境で障害注入を試す。','可靠性',0),
('it-local-technical-debt','技術的負債','ja','ぎじゅつてきふさい','技术债务：为短期收益作出的技术折衷，可能增加未来维护成本。','短期的な利点のために選んだ技術的な妥協が、将来の保守コストを増やす状態。','Technical debt is a trade-off that may increase future maintenance costs.','技術的負債を可視化して返済計画を立てる。','软件设计',0),
('it-local-code-review','コードレビュー','ja','こーどれびゅー','代码审查：由他人检查代码变更的正确性、可维护性和风险。','変更されたコードを他の開発者が確認し、品質やリスクを評価すること。','Code review evaluates changes for correctness, maintainability, and risk.','レビューでは仕様とテスト結果も確認する。','软件开发',0),
('it-local-static-analysis','静的解析','ja','せいてきかいせき','静态分析：不执行程序，通过源代码或字节码检查潜在问题。','プログラムを実行せずにソースコードなどを解析し、問題を検出する手法。','Static analysis examines code without executing the program.','静的解析をCIに組み込む。','测试',0),
('it-local-linter','リンター','ja','りんたー','代码检查工具：根据规则检测风格问题和部分潜在错误。','コーディング規約や潜在的な問題を自動検出するツール。','A linter detects style violations and some potential errors.','コミット前にリンターを実行する。','开发工具',0),
('it-local-type-checking','型チェック','ja','かたちぇっく','类型检查：验证表达式和变量的类型使用是否符合语言规则。','式や変数の型の使い方が言語の規則に合っているかを検証すること。','Type checking verifies that types are used consistently with language rules.','ビルド前に型チェックを実行する。','开发工具',0),
('it-local-environment-variable','環境変数','ja','かんきょうへんすう','环境变量：由运行环境向进程提供的配置值。','実行環境からプロセスへ設定値を渡す仕組み。','An environment variable passes configuration values to a process.','秘密情報をソースコードに直書きせず環境変数で管理する。','配置管理',0),
('it-local-secret-management','シークレット管理','ja','しーくれっとかんり','机密信息管理：安全存储和分发密码、令牌、密钥等敏感配置。','パスワード、トークン、鍵などの機密情報を安全に保管・配布すること。','Secret management securely stores and distributes passwords, tokens, and keys.','漏えい時にシークレットを失効してローテーションする。','安全与运维',0),
('it-local-config-drift','構成ドリフト','ja','こうせいどりふと','配置漂移：实际环境逐渐偏离期望或版本化的配置状态。','実環境の設定が、管理された望ましい状態からずれていくこと。','Configuration drift occurs when an environment diverges from its intended configuration.','構成ドリフトを検知して設定を同期する。','配置管理',0),
('it-local-infrastructure-as-code','Infrastructure as Code','ja','いんふらすとらくちゃーあずこーど','基础设施即代码：用可版本管理的配置描述和管理基础设施。','インフラの構成をコードで定義し、バージョン管理と自動適用を可能にする手法。','Infrastructure as Code manages infrastructure through versioned configuration files.','IaCの差分を確認してから適用する。','云与基础设施',0),
('it-local-blue-green-deployment','ブルーグリーンデプロイ','ja','ぶるーぐりーんでぷろい','蓝绿部署：维护两套环境，通过切换流量发布新版本并支持快速回退。','二つの環境を用意し、トラフィックの切り替えで新バージョンを公開する方式。','Blue-green deployment switches traffic between two environments for safer releases.','切り替え前に新環境のヘルスチェックを確認する。','软件发布',0),
('it-local-api-versioning','APIバージョニング','ja','えーぴーあいばーじょにんぐ','API 版本管理：通过版本策略管理接口变更，并降低对现有客户端的影响。','APIの変更をバージョンで管理し、既存クライアントへの影響を抑える方法。','API versioning manages interface changes while limiting client breakage.','後方互換性を保てない変更ではAPIバージョンを分ける。','API设计',0),
('it-local-backward-compatibility','後方互換性','ja','こうほうごかんせい','向后兼容性：新版本仍能与旧版本的客户端、数据或接口协作。','新しいバージョンが以前のクライアントやデータ形式と引き続き連携できる性質。','Backward compatibility lets newer versions continue working with older clients or data.','スキーマ変更の後方互換性を確認する。','软件设计',0),
('it-local-error-budget','エラーバジェット','ja','えらーばじぇっと','错误预算：在目标可靠性范围内允许服务出现的不可用或错误额度。','SLOで定めた信頼性目標に対して許容されるエラーの余地。','An error budget is the amount of unreliability permitted by an SLO.','エラーバジェットが少ない期間は変更リスクを抑える。','可靠性',0);
